import json
from typing import Tuple, Dict

todos = []
next_id = 1

def handle(method: str, path: str, body: bytes) -> Tuple[int, Dict]:
    global todos, next_id

    if method == 'GET' and path == '/todos':
        return (200, {'todos': todos, 'count': len(todos)})

    elif method == 'GET' and path == '/todos/priority':
        try:
            # Sort todos by priority
            priority_order = {'high': 0, 'medium': 1, 'low': 2}
            sorted_todos = sorted(todos, key=lambda t: priority_order.get(t.get('priority'), 2))
            return (200, {'todos': sorted_todos, 'count': len(sorted_todos)})
        except Exception as e:
            return (500, {'error': 'internal server error'})

    elif method == 'POST' and path == '/todos':
        try:
            data = json.loads(body.decode())
            text = data.get('text')
            priority = data.get('priority', 'high')  # Default to high priority

            if not text:
                return (400, {'error': 'text is required'})

            todo = {
                'id': next_id,
                'text': text,
                'completed': False,
                'priority': priority
            }
            todos.append(todo)
            next_id += 1
            return (201, {'todo': todo, 'count': len(todos)})
        except json.JSONDecodeError:
            return (400, {'error': 'invalid JSON'})

    elif method == 'PUT' and path.startswith('/todos/'):
        try:
            id = int(path.split('/')[-1])
            todo = next((t for t in todos if t['id'] == id), None)
            if not todo:
                return (404, {'error': 'todo not found'})

            todo['completed'] = not todo['completed']
            return (200, {'todo': todo, 'count': len(todos)})
        except ValueError:
            return (400, {'error': 'invalid id'})

    elif method == 'DELETE' and path.startswith('/todos/'):
        try:
            id = int(path.split('/')[-1])
            todo = next((t for t in todos if t['id'] == id), None)
            if not todo:
                return (404, {'error': 'todo not found'})

            todos = [t for t in todos if t['id'] != id]
            return (200, {'message': 'todo deleted', 'count': len(todos)})
        except ValueError:
            return (400, {'error': 'invalid id'})

    return (404, {'error': 'not found'})
