document.addEventListener('DOMContentLoaded', () => {
    const form = document.getElementById('todo-form');
    const input = document.getElementById('todo-input');
    const list = document.getElementById('todo-list');
    const prioritySelect = document.getElementById('priority-select');
    const todoCount = document.getElementById('todo-count');

    // 獲取待辦事項列表
    async function fetchTodos(sortBy = null) {
        try {
            let url = 'api/todos';
            if (sortBy) {
                url += `?sort=${sortBy}`;
            }
            const response = await fetch(url);
            const result = await response.json();
            renderTodos(result.todos || result);
            updateCount(result.count);
        } catch (error) {
            console.error('獲取待辦事項時出錯:', error);
        }
    }

    // 渲染待辦事項列表
    function renderTodos(todos) {
        list.innerHTML = '';
        todos.forEach(todo => {
            const li = document.createElement('li');
            li.innerHTML = `
                <span class="${todo.completed ? 'completed' : ''}">${todo.text}</span>
                <div>
                    <span class="priority ${todo.priority}">${todo.priority}</span>
                    <button class="complete-btn" data-id="${todo.id}">
                        ${todo.completed ? '取消完成' : '標記完成'}
                    </button>
                    <button class="delete-btn" data-id="${todo.id}">刪除</button>
                </div>
            `;
            list.appendChild(li);
        });
    }

    // 更新總數顯示
    function updateCount(count) {
        todoCount.textContent = count;
    }

    // 新增待辦事項
    form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const text = input.value.trim();
        const priority = prioritySelect.value;
        if (text) {
            try {
                await fetch('api/todos', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ text, priority })
                });
                input.value = '';
                prioritySelect.value = 'high';
                fetchTodos();
            } catch (error) {
                console.error('新增待辦事項時出錯:', error);
            }
        }
    });

    // 標記完成/取消完成待辦事項
    list.addEventListener('click', async (e) => {
        if (e.target.classList.contains('complete-btn')) {
            const id = e.target.dataset.id;
            try {
                await fetch(`api/todos/${id}`, { method: 'PUT' });
                fetchTodos();
            } catch (error) {
                console.error('更新待辦事項時出錯:', error);
            }
        }

        if (e.target.classList.contains('delete-btn')) {
            const id = e.target.dataset.id;
            try {
                await fetch(`api/todos/${id}`, { method: 'DELETE' });
                fetchTodos();
            } catch (error) {
                console.error('刪除待辦事項時出錯:', error);
            }
        }
    });

    // 排序按鈕事件處理
    document.getElementById('sort-high').addEventListener('click', () => fetchTodos('high'));
    document.getElementById('sort-medium').addEventListener('click', () => fetchTodos('medium'));
    document.getElementById('sort-low').addEventListener('click', () => fetchTodos('low'));
    document.getElementById('sort-default').addEventListener('click', () => fetchTodos());

    // 初始化
    fetchTodos();
});

